import{_ as o}from"./chunks/ark_flow_mr.CPEhZ0S2.js";import{_ as t}from"./chunks/ark_flow_orientation.PmYn6wPR.js";import{_ as i,c as n,o as l,al as c,j as e,a}from"./chunks/framework.CT7RwC5a.js";const A=JSON.parse('{"title":"ARK Flow MR","description":"","frontmatter":{},"headers":[],"relativePath":"ko/dronecan/ark_flow_mr.md","filePath":"ko/dronecan/ark_flow_mr.md"}'),d={name:"ko/dronecan/ark_flow_mr.md"};function h(s,r,f,m,_,u){return l(),n("div",null,r[0]||(r[0]=[c('<h1 id="ark-flow-mr" tabindex="-1">ARK Flow MR <a class="header-anchor" href="#ark-flow-mr" aria-label="Permalink to &quot;ARK Flow MR&quot;">​</a></h1><p>ARK Flow MR (&quot;Mid Range&quot;) is an open source <a href="./">DroneCAN</a> <a href="./../sensor/optical_flow.html">optical flow</a>, <a href="./../sensor/rangefinders.html">distance sensor</a>, and IMU module. It is the next generation of the <a href="./ark_flow.html">Ark Flow</a>, designed for mid-range applications.</p><p><img src="'+o+'" alt="ARK Flow MR"></p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><p>Order this module from:</p><ul><li><a href="https://arkelectron.com/product/ark-flow-mr/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="hardware-specifications" tabindex="-1">Hardware Specifications <a class="header-anchor" href="#hardware-specifications" aria-label="Permalink to &quot;Hardware Specifications&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_Flow_MR" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>센서 <ul><li>PixArt PAA3905 Optical Flow Sensor <ul><li>Auto detection of challenging conditions, such as checker boards, stripes, glossy surface and yawing</li><li>Wide working range from 80mm up to infinity</li><li>Automatic switching of Operation Mode</li><li>40mW IR LED built onto board for improved low light operation</li></ul></li><li>Broadcom AFBR-S50LX85D Time-of-Flight Distance Sensor <ul><li>Laser Opening Angle of 2° x 2°</li><li>Typical distance range up to 50m</li><li>Operation in up to 200 kilolux ambient light</li><li>Works well on all surface conditions</li></ul></li></ul></li><li>Invensense IIM-42653 6-Axis IMU</li><li>Two Pixhawk Standard CAN Connectors (4 Pin JST GH)</li><li>Pixhawk Standard Debug Connector (6 Pin JST SH)</li><li>Software controlled built-in CAN termination resistor via node parameter (CANNODE_TERM)</li><li>Small Form Factor <ul><li>3cm x 3cm x 1.4cm</li></ul></li><li>LED Indicators</li><li>USA Built</li></ul><h2 id="하드웨어-설정" tabindex="-1">하드웨어 설정 <a class="header-anchor" href="#하드웨어-설정" aria-label="Permalink to &quot;하드웨어 설정&quot;">​</a></h2><h3 id="배선" tabindex="-1">배선 <a class="header-anchor" href="#배선" aria-label="Permalink to &quot;배선&quot;">​</a></h3><p>The ARK Flow MR is connected to the CAN bus using a Pixhawk standard 4 pin JST GH cable. For more information, refer to the <a href="./../can/#wiring">CAN Wiring</a> instructions.</p><h3 id="장착" tabindex="-1">장착 <a class="header-anchor" href="#장착" aria-label="Permalink to &quot;장착&quot;">​</a></h3><p>The recommended mounting orientation is with the connectors on the board pointing towards <strong>back of vehicle</strong>, as shown in the following picture.</p><p><img src="'+t+'" alt="ARK Flow MR align with Pixhawk"></p><p>This corresponds to the default value (<code>0</code>) of the parameter <a href="./../advanced_config/parameter_reference.html#SENS_FLOW_ROT">SENS_FLOW_ROT</a>. Change the parameter appropriately if using a different orientation.</p><p>The sensor can be mounted anywhere on the frame, but you will need to specify the focal point position, relative to vehicle centre of gravity, during <a href="#px4-configuration">PX4 configuration</a>.</p><h2 id="firmware-setup" tabindex="-1">Firmware Setup <a class="header-anchor" href="#firmware-setup" aria-label="Permalink to &quot;Firmware Setup&quot;">​</a></h2><p>ARK Flow MR runs the <a href="./px4_cannode_fw.html">PX4 DroneCAN Firmware</a>. As such, it supports firmware update over the CAN bus and <a href="./#node-id-allocation">dynamic node allocation</a>.</p><p>ARK Flow MR boards ship with recent firmware pre-installed, but if you want to build and flash the latest firmware yourself see <a href="./px4_cannode_fw.html#building-the-firmware">PX4 DroneCAN Firmware &gt; Building the Firmware</a>.</p><ul><li>Firmware target: <code>ark_can-flow-mr_default</code></li><li>Bootloader target: <code>ark_can-flow-mr_canbootloader</code></li></ul><h2 id="flight-controller-setup" tabindex="-1">Flight Controller Setup <a class="header-anchor" href="#flight-controller-setup" aria-label="Permalink to &quot;Flight Controller Setup&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Ark Flow MR will not boot if there is no SD card in the flight controller when powered on.</p></div><h3 id="enable-dronecan" tabindex="-1">Enable DroneCAN <a class="header-anchor" href="#enable-dronecan" aria-label="Permalink to &quot;Enable DroneCAN&quot;">​</a></h3><p>단계는 다음과 같습니다:</p><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference.html#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation (or <code>3</code> if using <a href="./../dronecan/escs.html">DroneCAN ESCs</a>) and reboot (see <a href="./../advanced_config/parameters.html">Finding/Updating Parameters</a>).</li><li>Connect ARK Flow MR CAN to the Pixhawk CAN.</li></ul><p>Once enabled, the module will be detected on boot. Flow data should arrive at 100Hz. Distance sensor data should arrive at 40Hz.</p><p>DroneCAN configuration in PX4 is explained in more detail in <a href="./../dronecan/#enabling-dronecan">DroneCAN &gt; Enabling DroneCAN</a>.</p><h3 id="px4-설정" tabindex="-1">PX4 설정 <a class="header-anchor" href="#px4-설정" aria-label="Permalink to &quot;PX4 설정&quot;">​</a></h3><p>You need to set the EKF optical flow parameters to enable fusing optical flow measurements for velocity calculation, set necessary <a href="./">DroneCAN</a> parameters, and define offsets if the sensor is not centred within the vehicle.</p><p>Set the following parameters in <em>QGroundControl</em>:</p><ul><li>Enable optical flow fusion by setting <a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>.</li><li>To optionally disable GPS aiding, set <a href="./../advanced_config/parameter_reference.html#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a> to <code>0</code>.</li><li>Enable <a href="./../advanced_config/parameter_reference.html#UAVCAN_SUB_FLOW">UAVCAN_SUB_FLOW</a>.</li><li>Enable <a href="./../advanced_config/parameter_reference.html#UAVCAN_SUB_RNG">UAVCAN_SUB_RNG</a>.</li><li>Set <a href="./../advanced_config/parameter_reference.html#EKF2_RNG_A_HMAX">EKF2_RNG_A_HMAX</a> to <code>10</code>.</li><li>Set <a href="./../advanced_config/parameter_reference.html#EKF2_RNG_QLTY_T">EKF2_RNG_QLTY_T</a> to <code>0.2</code>.</li><li>Set <a href="./../advanced_config/parameter_reference.html#UAVCAN_RNG_MIN">UAVCAN_RNG_MIN</a> to <code>0.08</code>.</li><li>Set <a href="./../advanced_config/parameter_reference.html#UAVCAN_RNG_MAX">UAVCAN_RNG_MAX</a> to <code>50</code>.</li><li>Set <a href="./../advanced_config/parameter_reference.html#SENS_FLOW_MINHGT">SENS_FLOW_MINHGT</a> to <code>0.08</code>.</li><li>Set <a href="./../advanced_config/parameter_reference.html#SENS_FLOW_MAXHGT">SENS_FLOW_MAXHGT</a> to <code>25</code>.</li><li>Set <a href="./../advanced_config/parameter_reference.html#SENS_FLOW_MAXR">SENS_FLOW_MAXR</a> to <code>7.4</code> to match the PAW3902 maximum angular flow rate.</li><li>The parameters <a href="./../advanced_config/parameter_reference.html#EKF2_OF_POS_X">EKF2_OF_POS_X</a>, <a href="./../advanced_config/parameter_reference.html#EKF2_OF_POS_Y">EKF2_OF_POS_Y</a> and <a href="./../advanced_config/parameter_reference.html#EKF2_OF_POS_Z">EKF2_OF_POS_Z</a> can be set to account for the offset of the Ark Flow MR from the vehicle centre of gravity.</li></ul><h2 id="ark-flow-mr-configuration" tabindex="-1">Ark Flow MR Configuration <a class="header-anchor" href="#ark-flow-mr-configuration" aria-label="Permalink to &quot;Ark Flow MR Configuration&quot;">​</a></h2><p>You may need to <a href="./../dronecan/#qgc-cannode-parameter-configuration">configure the following parameters</a> on the ARK Flow MR itself:</p><table tabindex="0"><thead><tr><th>매개변수</th><th>설명</th></tr></thead><tbody><tr><td><a id="CANNODE_TERM"></a><a href="./../advanced_config/parameter_reference.html#CANNODE_TERM">CANNODE_TERM</a></td><td>CAN built-in bus termination.</td></tr></tbody></table><h2 id="led-신호의-의미" tabindex="-1">LED 신호의 의미 <a class="header-anchor" href="#led-신호의-의미" aria-label="Permalink to &quot;LED 신호의 의미&quot;">​</a></h2><p>You will see both red and blue LEDs on the ARK Flow MR when it is being flashed, and a solid blue LED if it is running properly.</p><p>If you see a solid red LED there is an error and you should check the following:</p><ul><li>Make sure the flight controller has an SD card installed.</li><li>Make sure the Ark Flow MR has <code>ark_can-flow-mr_canbootloader</code> installed prior to flashing <code>ark_can-flow-mr_default</code>.</li><li>Remove binaries from the root and ufw directories of the SD card and try to build and flash again.</li></ul><h2 id="비디오" tabindex="-1">비디오 <a class="header-anchor" href="#비디오" aria-label="Permalink to &quot;비디오&quot;">​</a></h2>',39),e("lite-youtube",{videoid:"SAbRe1fi7bU",params:"list=PLUepQApgwSozmwhOo-dXnN33i2nBEl1c0",title:"ARK Flow Indoor Position Hold x64"},null,-1),e("p",null,[e("em",null,[a("PX4 holding position using the ARK Flow MR sensor for velocity estimation (in "),e("a",{href:"./../flight_modes_mc/position.html"},"Position Mode"),a(").")])],-1),e("h2",{id:"see-also",tabindex:"-1"},[a("See Also "),e("a",{class:"header-anchor",href:"#see-also","aria-label":'Permalink to "See Also"'},"​")],-1),e("ul",null,[e("li",null,[e("a",{href:"https://arkelectron.gitbook.io/ark-documentation/sensors/ark-flow-mr",target:"_blank",rel:"noreferrer"},"ARK Flow MR"),a(" (ARK Docs)")])],-1)]))}const b=i(d,[["render",h]]);export{A as __pageData,b as default};
